insert into public.audit_criteria(niche,criterion_key,content) values
('Roofing','n-0','{"title":"Tipo de serviço e região","question":"Um cliente consegue identificar reparos, substituições e regiões realmente atendidas?","fix":"Especificar serviços reais e cidades cobertas, com CTA alinhado ao serviço."}'),
('Roofing','n-1','{"title":"Portfólio por tipo de telhado","question":"Projetos mostram situação, tipo de telhado e contexto, sem fotos genéricas?","fix":"Organizar fotos autênticas por tipo de intervenção, com autorização e contexto."}'),
('Remodeling','n-0','{"title":"Projetos comparáveis","question":"O visitante vê antes/depois legítimos e escopo de projetos próximos ao seu?","fix":"Documentar trabalhos e resultados verificáveis, incluindo o escopo da reforma."}'),
('Remodeling','n-1','{"title":"Consulta e qualificação","question":"É claro o processo inicial, os serviços possíveis e o que informar para orçar?","fix":"Explicar a consulta, região, tipo de projeto e informações mínimas necessárias."}'),
('HVAC','n-0','{"title":"Emergência versus manutenção","question":"O caminho para urgência está separado de manutenção programada?","fix":"Criar ações claras para urgência e manutenção, sem prometer disponibilidade não confirmada."}'),
('HVAC','n-1','{"title":"Disponibilidade e cidades","question":"As áreas e horários de atendimento são confiáveis e fáceis de encontrar?","fix":"Mostrar cobertura e horários reais junto das ações de agendamento."}'),
('Plumbing','n-0','{"title":"Telefone clicável em emergência","question":"Em celular, o telefone abre a ligação e informa se há atendimento urgente?","fix":"Usar link tel: funcional, serviço identificado e disponibilidade real no destaque."}'),
('Plumbing','n-1','{"title":"Tipo de reparo e região","question":"O cliente sabe se a equipe atende seu reparo e sua cidade?","fix":"Organizar categorias de reparo e cobertura real perto dos contatos."}'),
('Electrical','n-0','{"title":"Instalações e especialidades","question":"A pessoa identifica a especialidade necessária sem interpretação técnica?","fix":"Separar instalação, reparo e inspeções com explicação leiga e ação específica."}'),
('Electrical','n-1','{"title":"Credenciais relevantes","question":"Licenças e habilitações são apresentadas sem afirmações genéricas?","fix":"Exibir credenciais atuais, quando aplicáveis, e modos de verificação."}'),
('Odontologia','n-0','{"title":"Tratamentos claros","question":"Tratamentos, localização e indicação de consulta estão claros?","fix":"Organizar tratamentos em linguagem acessível, sem garantias clínicas."}'),
('Odontologia','n-1','{"title":"Agendamento com contexto","question":"A reserva explica o próximo passo e evita pedir dados sensíveis desnecessários?","fix":"Simplificar a solicitação de consulta e explicar retorno, duração e localização."}'),
('Med spas','n-0','{"title":"Segurança e profissionais","question":"O responsável técnico e os limites do procedimento estão identificados?","fix":"Mostrar profissionais habilitados e informações verificáveis de segurança."}'),
('Med spas','n-1','{"title":"Reserva por tratamento","question":"A pessoa sabe qual consulta solicitar e como ocorrerá a avaliação?","fix":"Criar CTAs por categoria, incluindo consulta de avaliação quando necessária."}'),
('Advocacia','n-0','{"title":"Área jurídica e local de atuação","question":"A especialidade e a jurisdição atendida aparecem sem ambiguidades?","fix":"Especificar áreas reais e localização, preservando confidencialidade e regras profissionais."}'),
('Advocacia','n-1','{"title":"Credenciais sem garantia de resultado","question":"Experiência e credenciais não sugerem resultado jurídico garantido?","fix":"Usar credenciais verificáveis e descrever o processo de consulta com clareza."}'),
('House cleaning','n-0','{"title":"Modalidades e inclusões","question":"O cliente entende limpeza recorrente, profunda e o que está incluído?","fix":"Apresentar opções, inclusões, exclusões e como obter um orçamento."}'),
('House cleaning','n-1','{"title":"Provas de confiança","question":"Fotos e avaliações reais tornam compreensível a confiança na equipe?","fix":"Apresentar avaliações autênticas, processo de contratação e protocolos verdadeiros."}'),
('Restaurantes','n-0','{"title":"Cardápio utilizável","question":"O cardápio abre rápido no celular, está legível e mostra informação essencial?","fix":"Publicar cardápio móvel acessível e manter preços, opções e horários atualizados."}'),
('Restaurantes','n-1','{"title":"Pedido, reserva e horário","question":"O visitante consegue escolher pedido, reserva ou visita com horários corretos?","fix":"Separar ações de pedido e reserva, informar horário e testar os destinos."}')
